INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 1, 5, 'go',
  'Peak Cauvery island window. 17-29C, dry. Ranganathaswamy, Dariya Daulat, Gumbaz clean access.',
  'January is when Srirangapatna runs at its strongest. Daytime 25-29C, nights 17-19C. Ranganathaswamy Temple (Adi Ranga, 9c CE), Dariya Daulat Bagh (1784 Tipu summer palace), Gumbaz (Tipu''s mausoleum), Tipu''s Death Spot all on clean walking access.',
  NULL,
  'Srirangapatna in January is the version every Karnataka heritage traveller books first. The Cauvery river island — 5km long, 1km wide, the Tipu Sultan Mysore Sultanate capital 1782-1799 — sits 14km north of Mysore, the standard heritage day-trip from the palace city. Daytime 25-29C, nights 17-19C, humidity 60 percent. Ranganathaswamy Temple (the Adi Ranga of the three sacred Vishnu islands — Adi Ranga Srirangapatna, Madhya Ranga Shivasamudram, Antya Ranga Srirangam Tamil Nadu, 9th-century Ganga Dynasty origins, expanded by Hoysalas and Vijayanagara) holds 6.30am-1pm + 4-8pm, ₹free. The recumbent Vishnu sculpture on the serpent Adi Shesha is the largest such Vishnu in South India. Dariya Daulat Bagh (1784, Tipu Sultan''s summer palace, ASI-managed, ₹25 Indian, 9am-5pm) — the Persian-style frescoes on the walls of the Indo-Saracenic teak structure depict the 1780 Battle of Pollilur in which Tipu and Hyder Ali defeated Colonel Baillie of the British East India Company. Gumbaz (1784 Tipu''s mausoleum where he, Hyder Ali, and Tipu''s mother are interred, ASI-managed, ₹15) 9am-5pm.'
)
