INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 2, 5, 'go',
  'Driest month. 18-31C, humidity 55 percent. Heritage walking at year-best. Day-trip from Mysore at full ease.',
  'February is Srirangapatna''s cleanest weather window — rainfall under 5mm. Ranganathaswamy, Dariya Daulat, Gumbaz, Wellesley Bridge, Colonel Bailey''s Dungeon all on clean walking circuit. Standard day-trip from Mysore.',
  NULL,
  'Srirangapatna in February is the technical peak. Rainfall under 5mm, daytime 27-31C, nights 18-20C, humidity at year-low 55 percent. The Cauvery river island heritage circuit — Ranganathaswamy Temple (the Adi Ranga of the three Ranganatha temples, 9th-century Ganga origins, the recumbent Vishnu the largest in South India), Dariya Daulat Bagh (1784 Tipu Sultan summer palace, ASI ₹25 Indian, 9am-5pm), Gumbaz (1784 Tipu''s mausoleum, ASI ₹15), Tipu''s Death Spot, Colonel Bailey''s Dungeon, Wellesley Bridge — works as a 4-5 hour comfortable circuit. The Battle of Srirangapatna (May 4, 1799 — British forces under Wellesley and Baird stormed the fortress, killing Tipu at the breach, ending the Mysore Sultanate and triggering the Wodeyar restoration; the event marked the strategic British takeover of South India) site markers throughout the island. Dariya Daulat Bagh''s Persian-style frescoes — including the celebrated wall painting of the 1780 Battle of Pollilur (Tipu and Hyder Ali defeating Colonel Baillie) — hold year-clearest visibility in the dry weather. Karighatta Hill (15km, the Vaikuntha Venkataramana Swamy temple at 2700ft) at clean afternoon access.'
)
