INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 3, 4, 'go',
  'Warming. 20-33C, humidity 60 percent. Heritage walking till 11am. Last clean window.',
  'March extends February''s pattern with rising mid-day heat. Heritage walking compresses to 7-11am and 5-9pm. Ranganathittu Bird Sanctuary at peak nesting season — painted storks, openbill storks at clearest visibility.',
  NULL,
  'Srirangapatna in March is the soft-landing month. Daytime 28-33C, nights 20-22C, humidity climbing toward 65 percent in the last fortnight, rainfall under 20mm. Heritage walking compresses to 7-11am and 5-9pm windows. Ranganathaswamy Temple (Adi Ranga, 9th-century, ₹free 6.30am-1pm + 4-8pm), Dariya Daulat Bagh (1784 Tipu summer palace, ASI ₹25 Indian, 9am-5pm), Gumbaz (1784 mausoleum, ASI ₹15, 9am-5pm) all hold full hours. The Persian frescoes inside Dariya Daulat (the depiction of the 1780 Battle of Pollilur — Tipu Sultan defeating Colonel Baillie of the British East India Company) hold cool interior visibility through the heat. Tipu''s Death Spot, Colonel Bailey''s Dungeon, Wellesley Bridge accessible. Ranganathittu Bird Sanctuary (3km, Karnataka Forest Department, ₹400 boat safari) at peak nesting season — painted storks, Eurasian spoonbills, Asian openbills, black-headed ibis, river terns, marsh crocodiles at year-best visibility. The 30-min boat safari runs 8.30am-6pm; book the 8.30am or 5pm slots for clean morning/evening light. Holi long weekend (variable mid-March, 2026) brings 3-day domestic bump from Bengaluru-Mysore.'
)
