INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 4, 3, 'wait',
  'Pre-monsoon heat. 23-36C, humidity 70 percent. Outdoor heritage walks collapse mid-day.',
  'April still works for early-morning + late-afternoon heritage circuit. Outdoor walking 11am-5pm unviable. Ranganathittu Bird Sanctuary 8.30am-9am batch only. Most visitors compress to a half-day Mysore day-trip.',
  'April pushes Srirangapatna into mid-day endurance. 30-36C, humidity 70 percent, the open-air heritage circuit (Dariya Daulat courtyard, Gumbaz garden, Wellesley Bridge approach) unviable 11am-5pm. Push to October-November for clean walking weather.',
  'Srirangapatna in April narrows to early morning and post-sunset. Daytime 30-36C, nights 23-25C, humidity 70 percent. The open-air heritage circuit — Dariya Daulat Bagh courtyards, Gumbaz garden approach, Wellesley Bridge walk, Colonel Bailey''s Dungeon outdoor access — collapses 11am-5pm. The Tipu Sultan-era Indo-Saracenic structures (built 1784 and ASI-restored) hold cool interiors but the walks between them become punishing. Ranganathaswamy Temple (Adi Ranga, ₹free, 6.30am-1pm + 4-8pm) holds interior cool through the heat but the queue under sun gets brutal. Dariya Daulat Bagh (ASI ₹25 Indian, 9am-5pm) — go 9-10.30am or 4-5pm. Gumbaz (ASI ₹15, 9am-5pm) — early or late only. Ranganathittu Bird Sanctuary (3km, KFD ₹400 boat safari) at 8.30am batch only — the 4-6pm batch viable but post-monsoon (Oct-Nov) bird counts are dramatically higher. Most visitors compress to a half-day Mysore-Srirangapatna 8am-noon return. Hotel rates 25-30 percent below February: Mayura Riverview KSTDC ₹2,000-3,000, Fern Resort ₹3,000-4,500. October-November is the clean shape.'
)
