INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 5, 3, 'wait',
  'Pre-monsoon heat plus storms. 23-35C, humidity 75 percent. Hotel rates year-low.',
  'May still works for the dawn-only heritage visit but pre-monsoon thunderstorms cancel afternoon plans. Power-cut risk 1-2 hours daily. Hotel rates at year-low. Wait for October.',
  'May at Srirangapatna is the pre-monsoon endurance month. 27-35C, humidity 75 percent, thunderstorms cancel afternoon plans. Outdoor heritage walking compresses to dawn-9am and post-7pm. Wait for October.',
  'Srirangapatna in May is the pre-monsoon transition. Daytime 30-35C, nights 23-25C, humidity climbing past 75 percent in the last fortnight, rainfall 80-130mm with pre-monsoon thunderstorms hitting 3-5 evenings per week. Power cuts run 1-2 hours daily through the last 10 days as CHESCOM grid struggles. The outdoor heritage circuit — Ranganathaswamy Temple approach, Dariya Daulat courtyards, Gumbaz garden, Wellesley Bridge, Colonel Bailey''s Dungeon — compresses to 6-9am and 6-8pm windows. Ranganathaswamy Temple (Adi Ranga, ₹free, 6.30am-1pm + 4-8pm) interior cool throughout. Dariya Daulat Bagh (ASI ₹25 Indian, 9am-5pm) — early morning only. The Persian frescoes inside (depicting the 1780 Battle of Pollilur where Tipu Sultan and Hyder Ali defeated Colonel Baillie) hold cool interior visibility. Gumbaz (ASI ₹15, 9am-5pm) — early morning. Ranganathittu Bird Sanctuary (3km, KFD ₹400 boat safari) at 8.30am batch only — water levels low pre-monsoon, bird counts moderate. Hotel rates at year-low: Mayura Riverview KSTDC ₹1,800-2,800, Fern Resort ₹2,500-4,000. The October-March window is dramatically better — push the trip there if it can move.'
)
