INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 6, 4, 'go',
  'SW monsoon arrives. 22-29C, 70-100mm rainfall. Cauvery filling. Heritage circuit on full schedule.',
  'June is when the SW monsoon hits. Temperatures ease to 22-29C, rainfall 70-100mm — light compared to coastal Karnataka. Cauvery river filling makes the island setting at year-greenest. Heritage circuit at full operational tempo.',
  NULL,
  'Srirangapatna in June is the year''s most comfortable stretch by temperature — the southwest monsoon arrives in the first fortnight (Karnataka inland onset June 5-10), bringing 70-100mm rainfall across 12-15 wet days, almost all as 2-3 hour afternoon downpours. Daytime 25-29C, nights 22-24C, humidity 80 percent. Srirangapatna sits at 685m elevation in the partial rain-shadow of the Western Ghats — far lighter than coastal Mangalore (1000mm in June) or Coorg (600-800mm). The Cauvery river starts filling from upstream KRS Dam releases — the island setting at year-greenest from late June onward. Ranganathaswamy Temple (Adi Ranga, ₹free, 6.30am-1pm + 4-8pm), Dariya Daulat Bagh (ASI ₹25 Indian, 9am-5pm), Gumbaz (ASI ₹15, 9am-5pm) all hold full schedule. The Persian frescoes inside Dariya Daulat (1780 Battle of Pollilur depiction) hold interior visibility through monsoon humidity. Tipu''s Death Spot marker, Colonel Bailey''s Dungeon, Wellesley Bridge accessible. Ranganathittu Bird Sanctuary (3km, KFD ₹400 boat safari, 8.30am-6pm) — water level rising, monsoon nesting just beginning. Marsh crocodile visibility climbs.'
)
