INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 7, 4, 'go',
  'SW monsoon. 22-27C, 80-110mm rainfall. Cauvery at peak flow. Heritage circuit works.',
  'July holds the June pattern — 80-110mm rainfall, Cauvery at peak monsoon flow, the island setting at year-greenest. Heritage circuit at full operational tempo. KRS Dam upstream releases visible from Wellesley Bridge.',
  NULL,
  'Srirangapatna in July is the second comfortable monsoon month — 80-110mm rainfall across 15-18 wet days, materially lighter than coastal Karnataka (Mangalore 800-1000mm) or the Western Ghats (Coorg 800-1000mm). Daytime 24-27C, nights 22-24C, humidity 85 percent. The Cauvery river at peak monsoon flow — KRS Dam upstream at full reservoir level (124.8ft maximum) releases visible from Wellesley Bridge, the island setting at year-greenest. Ranganathaswamy Temple (Adi Ranga, ₹free, 6.30am-1pm + 4-8pm) holds interior cool throughout. Dariya Daulat Bagh (1784 Tipu summer palace, ASI ₹25 Indian, 9am-5pm) — the Persian frescoes (1780 Battle of Pollilur depiction, Tipu defeating Colonel Baillie of the British East India Company) hold strongest interior visibility. Gumbaz (1784 mausoleum, ASI ₹15, 9am-5pm) at clean morning visit. Tipu''s Death Spot (the marker stone where British forces killed Tipu on May 4, 1799), Colonel Bailey''s Dungeon, Wellesley Bridge accessible. Ranganathittu Bird Sanctuary (3km, KFD ₹400 boat safari, 8.30am-6pm) — water level at peak, the marsh crocodile sightings the year-best, monsoon-breeding waterbirds active. Birding 8.30am batch strongest.'
)
