INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 8, 4, 'go',
  'SW monsoon continues. 22-28C, 90-120mm rainfall. Cauvery still strong. Heritage circuit on schedule.',
  'August holds the July pattern. KRS Dam at peak reservoir level brings strong Cauvery flow past the island. Heritage circuit at full tempo. Independence Day weekend (Aug 15) brings 3-day domestic bump from Bengaluru-Mysore.',
  NULL,
  'Srirangapatna in August holds the July monsoon pattern with slightly more rain days. 90-120mm rainfall across 17-20 wet days, daytime 24-28C, nights 22-24C, humidity 85 percent. The Cauvery river still strong past the island — KRS Dam upstream at peak monsoon reservoir level (124.8ft maximum) drives strong flow past Wellesley Bridge. Ranganathaswamy Temple (Adi Ranga, 9th-century Ganga origins, ₹free, 6.30am-1pm + 4-8pm), Dariya Daulat Bagh (1784 Tipu summer palace, ASI ₹25 Indian, 9am-5pm), Gumbaz (1784 mausoleum, ASI ₹15, 9am-5pm) all on full schedule. The Persian frescoes inside Dariya Daulat (depicting the 1780 Battle of Pollilur where Tipu Sultan and Hyder Ali defeated Colonel Baillie) hold strongest interior visibility through the humid weather. Tipu''s Death Spot, Colonel Bailey''s Dungeon, Wellesley Bridge accessible. Ranganathittu Bird Sanctuary (3km, KFD ₹400 boat safari, 8.30am-6pm) at peak nesting season — painted storks, Asian openbills, Eurasian spoonbills, black-headed ibis, river terns, marsh crocodiles at strong visibility. Independence Day (Aug 15) brings a 3-day weekend bump from Bengaluru, Mysore, Chennai.'
)
