INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 9, 5, 'go',
  'Mysore Dasara halo. 21-29C. Island runs heritage-and-temple traffic from Dasara pilgrims.',
  'September is when Mysore Dasara (Sep 22 - Oct 1, 2026) draws international heritage tourists, and Srirangapatna (14km north) catches the spillover. Ranganathaswamy and Dariya Daulat at peak visitor traffic. Hotel rates climb 30-50 percent during Dasara week.',
  NULL,
  'Srirangapatna in September is when the island catches the Mysore Dasara halo. The 10-day Karnataka state festival runs September 22 to October 1, 2026 — Mahanavami September 29, Vijayadashami September 30 — and Srirangapatna (14km north of Mysore on NH-275) absorbs the heritage-tourist spillover. Daytime 24-29C, nights 21-23C, humidity easing toward 75 percent, rainfall 90-120mm — SW monsoon retreats from Karnataka by Sep 20-25. Ranganathaswamy Temple (Adi Ranga of the three sacred Vishnu islands, 9th-century Ganga Dynasty origins, ₹free, 6.30am-1pm + 4-8pm) — Dasara pilgrims fill the queue with the recumbent Vishnu setpiece in higher demand. Dariya Daulat Bagh (1784 Tipu Sultan summer palace, ASI ₹25 Indian, 9am-5pm) — international Dasara visitors fill the Persian fresco rooms 10am-4pm; the 1780 Battle of Pollilur fresco depicting Tipu and Hyder Ali defeating Colonel Baillie holds peak visitor traffic. Gumbaz (1784 mausoleum, ASI ₹15, 9am-5pm). Tipu''s Death Spot, Colonel Bailey''s Dungeon, Wellesley Bridge accessible. Ranganathittu Bird Sanctuary (3km, KFD ₹400 boat safari, 8.30am-6pm) at recovering post-monsoon visibility.'
)
