INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 10, 5, 'go',
  'Dasara tail + season open. 20-29C. Post-Vijayadashami clean weather. Heritage circuit at peak ease.',
  'October is Dasara tail (Sep 22 - Oct 1 finale at Mysore) into clean post-monsoon weather. Mysore-Srirangapatna 14km drive at full ease. Heritage circuit at peak walking comfort. Hotel rates ease 30 percent after Dasara week.',
  NULL,
  'Srirangapatna in October is when the island pivots from peak Dasara pilgrim traffic to clean post-monsoon walking weather. Mysore Dasara 2026 ends October 1 (Vijayadashami the previous day); from October 2 the heritage circuit returns to normal weekday-light visitor flow. Daytime 24-29C, nights 20-22C, humidity dropping toward 70 percent, rainfall 100-140mm — northeast monsoon overspill from Tamil Nadu hits mostly as 1-2 hour evening showers in the first fortnight. The Cauvery river still strong from the SW monsoon recession — Wellesley Bridge walking views at year-photogenic. Ranganathaswamy Temple (Adi Ranga, ₹free, 6.30am-1pm + 4-8pm), Dariya Daulat Bagh (1784 Tipu summer palace, ASI ₹25 Indian, 9am-5pm), Gumbaz (1784 mausoleum, ASI ₹15, 9am-5pm) all on clean visitor flow from October 2 onward. The Persian frescoes inside Dariya Daulat (1780 Battle of Pollilur depiction) at year-best interior visibility — the post-monsoon humidity drop reveals fresco detail otherwise muted in May-September. Tipu''s Death Spot, Colonel Bailey''s Dungeon, Wellesley Bridge accessible.'
)
