INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 11, 5, 'go',
  'High season builds. 18-28C, dry. Heritage walking at peak. Ranganathittu birding window opens.',
  'November is the genuine pivot to Srirangapatna high season. Rainfall under 50mm, humidity 60 percent, full heritage walking weather. Ranganathittu Bird Sanctuary winter migrant arrivals begin. Karnataka Rajyotsava Nov 1.',
  NULL,
  'Srirangapatna in November is when the island turns to its second-strongest stretch after Dasara. Northeast monsoon overspill spent by mid-month, rainfall under 50mm across 4-6 wet days. Daytime 25-28C, nights 18-20C, humidity 60 percent — among the cleanest weather across South India heritage destinations. The Cauvery river at sustained post-monsoon flow makes Wellesley Bridge views and the Karighatta Hill viewline at year-photogenic. Karnataka Rajyotsava (November 1, State Formation Day 1956) brings state-wide celebration — Ranganathaswamy Temple sees a 1-day pilgrim spike. Ranganathaswamy Temple (Adi Ranga of the three Vishnu islands, 9th-century Ganga origins, ₹free, 6.30am-1pm + 4-8pm), Dariya Daulat Bagh (1784 Tipu summer palace, ASI ₹25 Indian, 9am-5pm — the Persian frescoes including the 1780 Battle of Pollilur depiction), Gumbaz (1784 mausoleum holding Tipu, Hyder Ali, and Tipu''s mother''s tombs, ASI ₹15, 9am-5pm), Tipu''s Death Spot, Colonel Bailey''s Dungeon, Wellesley Bridge all on full schedule.'
)
