INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srirangapatna', 12, 5, 'go',
  'Peak season. 17-27C, dry. Heritage walking at year-best. Ranganathittu birding at peak. Christmas-NYE rates climb.',
  'December is the year''s most reliable Srirangapatna window — peak weather, dry, full operational tempo. Ranganathittu winter migrants at peak. Hotel rates climb 25-35 percent over Christmas-NYE week.',
  NULL,
  'Srirangapatna in December is the year''s most coherent post-Dasara window — peak weather, full operational tempo, the Cauvery island at year-cleanest. Daytime 23-27C, nights 17-19C, humidity 55 percent, rainfall under 10mm. Ranganathaswamy Temple (Adi Ranga of the three Vishnu islands, 9th-century Ganga Dynasty origins, the recumbent Vishnu on Adi Shesha the largest such Vishnu in South India, ₹free, 6.30am-1pm + 4-8pm) at peak weekend visitor flow. Dariya Daulat Bagh (1784 Tipu Sultan summer palace, ASI ₹25 Indian, 9am-5pm) — the Persian-style frescoes including the celebrated 1780 Battle of Pollilur wall painting (Tipu Sultan and Hyder Ali defeating Colonel Baillie of the British East India Company) hold year-cleanest interior visibility. Gumbaz (1784 mausoleum, the resting place of Tipu Sultan killed at the May 4, 1799 storming of Srirangapatna by Wellesley and Baird, also of Hyder Ali and Tipu''s mother Fakhr-un-Nissa, ASI ₹15, 9am-5pm). Tipu''s Death Spot marker stone, Colonel Bailey''s Dungeon, Wellesley Bridge all at clean visitor flow.'
)
